#!/usr/bin/env python3
"""Generate public quality documentation and the bilingual Sources page from the ledger."""
import html,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
load=lambda p:json.loads((ROOT/p).read_text())
def variable(file,name):return json.loads((ROOT/file).read_text().split('const '+name+' = ',1)[1].removesuffix(';\n'))
D=variable('catalog.js','DB');M=variable('media.js','MEDIA');A=load('data/audit.json');R=load('data/reference/official.json');C=load('data/reference/categories.json');E=load('data/editorial.json');N=load('data/reference/research-notes.json')
B,S,F,T=[D[k] for k in ['books','stories','films','tower']]
img=A['images'];counts={k:len(D[k]) for k in ['books','stories','films','tower','works','editions']}
missingNL=[b['Engelse titel'] for b in B if not M['books'].get(b['Engelse titel'],{}).get('nl')];missingEN=[b['Engelse titel'] for b in B if not M['books'].get(b['Engelse titel'],{}).get('en')];missingPosters=[f"{f['Verfilming (EN)']} ({f.get('Jaar') or 'jaar onbevestigd'})" for f in F if f"{f['Verfilming (EN)']}|{f.get('Jaar')}" not in M['films']]
sourceByWork={r['workId']:r for r in B};standalone=[s for s in S if s.get('standaloneBookId') or s.get('standalonePublications')];ownCounts={lang:sum(bool(M['stories'].get(s['Engelse verhaalnaam'],{}).get(lang) or M['books'].get(sourceByWork.get(s['workId'],{}).get('Engelse titel'),{}).get(lang)) for s in standalone) for lang in ['nl','en']}
coverUses={lang:0 for lang in ['nl','en']}
for s in S:
 if not s.get('defaultCollectionId'):continue
 b=next(b for b in B if b['id']==s['defaultCollectionId']);bm=M['books'].get(b['Engelse titel'],{})
 for lang in ['nl','en']:
  if bm.get(lang) or (lang=='nl' and bm.get('en')):coverUses[lang]+=1
summary={'catalog':counts,'images':img,'missingImages':{'nl':len(missingNL),'en':len(missingEN),'posters':len(missingPosters)},'storyCovers':dict(A['storyCovers'],verifiedOwnCovers=ownCounts,collectionCoverUse=coverUses),'referenceCoverage':A['referenceCoverage'],'sourceRowCount':len(R['index']),'sourceDetailsChecked':len(R['details']),'collaborations':A['collaborations']}
(ROOT/'data/quality-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
lines=['# The Kingverse 1.5.1 — catalogusaudit en datakwaliteit','', 'Peildatum: **25 oktober 2026**. Dit rapport beschrijft een reproduceerbare auditbatch. Het archief is aantoonbaar uitgebreid; de volledige bibliografie, eerste-publicatiegeschiedenis en alle afgeleide adaptaties zijn **niet** volledig onafhankelijk geverifieerd. Op verzoek ligt de afronding nu eerst bij de Engelse structuur, pagina’s en gegevens. Engels is de standaard voor nieuwe bezoekers; bestaande NL-functionaliteit blijft behouden, verdere Nederlandse uitwerking en beeldresearch zijn latere fasen.','', '## Bronnen en scope','', f"De primaire standaard is [StephenKing.com — works/all/](https://stephenking.com/works/all/): {len(R['index'])} bronregels. Er zijn {len(R['details'])} detailpagina’s uit de fictie-/adaptatiescope gecontroleerd op gestructureerde metadata. De [officiële bibliografie](https://stephenking.com/bibliography/) leverde daarnaast 692 feitelijke publicatievermeldingen. We bewaren bron-URL’s, peildatum, bronhashes, datumprecisie en gecontroleerde velden in `data/reference/` en `data/audit.json`. Geen synopsisteksten zijn overgenomen in de bronadministratie.",'', 'Gespecialiseerde overzichten zijn volledig naast de hoofdindex gelegd:','', '| Overzicht | Bronregels | Bron |','| --- | ---: | --- |']
for c in C['categories']:lines.append(f"| {c['category']} | {len(c.get('records',[]))} | [Officieel overzicht]({c['source']}) |")
lines+=['','De romanlijst omvat ook novellen en heruitgaven; de short-lijst omvat naast fictie essays, poëzie, interviews en toespraken. De hoofdindex telt 58 Movie-regels, het gespecialiseerde filmoverzicht 57. Firestarter (1984 en 2022) heeft in de hoofdindex twee vermeldingen met dezelfde URL die naar de 2022-film leidt. De veldcontrole voorkomt dat de credits en poster daardoor naar de verkeerde film worden gekopieerd.','', 'Voor Nederlandse edities zijn 94 pagina’s uit de officiële Luitingh-Sijthoff-auteurscatalogus verwerkt. Van 110 fanclubpagina’s leverden 81 HTTP 503; die zijn als onbereikbaar vastgelegd, zonder omzeiling. De gecontroleerde uitgeverspagina’s geven titel, taal en ISBN/beeld. Een ontbrekende Nederlandse editie in deze dataset betekent niet dat er geen vertaling bestaat.','', '## Onafhankelijke verificatie en Brooks','', f"Justin Brooks’ *Stephen King: A Primary Bibliography of the World’s Most Popular Author* is gecontroleerd via [de uitgever]({N['brooks']['publisherMetadataSource']}) en [WorldCat]({N['brooks']['libraryMetadataSource']}). De geraadpleegde publicatiegegevens betreffen de editie van mei 2008, Cemetery Dance, 560 pagina’s, ISBN 1-58767-153-0. De uitgeversbeschrijving noemt dekking tot eind 2005 en veel meer soorten bijdragen en verschijningsvormen dan onze fictiescope. Die aantallen zijn dus geen vervangende telling van unieke werken.", '', 'Er is **geen volledige, geautoriseerde tekst of systematische entry-voor-entrycontrole van Brooks** uitgevoerd. Een zoekresultaat bood een externe 2013-tekstspiegel; de herkomst/volledigheid is niet vastgesteld en die is niet als geverifieerde hoofdlijst gebruikt. Diepgaande eerste-publicatiecontrole, obscure bijdragen en overige genres blijven open.','', 'Films/TV zijn primair gecontroleerd met de officiële King-detailpagina’s en bibliografie, aangevuld met Amazon/Prime Video, Hulu, Paramount en NEON voor actuele of conflicterende feiten. [De onafhankelijke adaptatielijst](https://en.wikipedia.org/wiki/List_of_adaptations_of_works_by_Stephen_King) is voor aanvullende kandidaatgroepen bekeken; die kandidaten zijn niet automatisch als bevestigde releases geïmporteerd.','', '## Werk is niet hetzelfde als uitgave','', f"Er zijn {counts['works']} unieke literaire identiteiten in `works`. De bibliotheek heeft {len(B)} records; de verhalenpagina {len(S)} unieke verhaal-/bundelbijdragen. Drie zelfstandig uitgegeven novellen zijn vanuit beide indexen bereikbaar en delen één `workId`. Gelijknamige verhalen en bundels (zoals *Hearts in Atlantis*) blijven verschillende werken. {counts['editions']} vastgelegde editievoorbeelden verwijzen naar een werk, taal, bron en waar bekend ISBN. Een cover verwijst naar zo’n editie.", '', '- The Green Mile is één literair werk. De zes seriële publicaties uit 1996 en de verzamelde editie worden als publicatiegeschiedenis vastgelegd, niet als zeven extra romans. De bronvermelding 2000 bij een latere verzamelde editie overschrijft de seriële start van maart 1996 niet.', '- Vier heruitgaven/versies uit de romanindex zijn gekoppeld aan hun oorspronkelijke werk. Zij verhogen het aantal unieke werken niet.', '- Een verhaal dat in meerdere bundels voorkomt staat één keer in de verhalenindex, met meerdere bundelkoppelingen. De vier Bachman-romans uit *The Bachman Books* zijn als boeken gekoppeld en niet meer misleidend als korte verhalen geteld.', '- Een bronregistratiedatum is geen bewezen eerste publicatie. Datumprecisie blijft jaar/maand/dag; onafhankelijke eerste-publicatiegeschiedenis staat per record nog open tenzij uitdrukkelijk onderbouwd.','', '## Dekking per categorie','', '“Titel vergeleken” betekent dat het record tegen een genoemde bron is gelegd; het betekent **niet** dat alle velden onafhankelijk bevestigd zijn. “Onzekere metadata” telt records met ten minste één open auditveld, inclusief eerste-publicatiegeschiedenis.','', '| Categorie | Verwacht volgens vastgelegde scope | Aanwezig | Titel vergeleken | Ontbrekende bronwerken | Records met onzekere metadata |','| --- | ---: | ---: | ---: | ---: | ---: |']
for cat,arr,label in [('books',B,'Boeken/bundels + afgebakende samenwerkingsuitbreiding'),('stories',S,'Korte fictie + behouden overige bundelbijdragen'),('films',F,'Film/TV uit primaire lijst + aanvullingen')]:
 cv=A['referenceCoverage'][cat];checked=sum('title' in r['audit']['fields'] for r in arr);lines.append(f"| {label} | {cv['expectedUniqueWorks']} | {len(arr)} | {checked} | {len(cv['missing'])} | {cv['uncertainRecords']} |")
lines+=['', f"De 166 unieke korte-fictiewerken corresponderen met 168 afzonderlijke officiële URL’s: *N/N.* en *The Glass Floor* komen in meerdere bronrubrieken voor; daarnaast bevat de index een herhaalde Glass Floor-vermelding. Er blijven zeven bestaande bijdragen buiten die fictionele types behouden (zoals gedichten, een essay en een scenario). De film/TV-telling omvat 90 primaire bronentiteiten en zes aanvullende records. De boekenvergelijking omvat ook {A['publicationRecordsCompared']} publicatie-/werkregels vóór werk/uitgave-consolidatie, plus de vier afzonderlijk toegevoegde samenwerkingsprojecten.", '', 'Alle bronrecords binnen deze **vastgestelde inventarisatiescope zijn vergeleken**. Geen van deze categorieën wordt als volledig onafhankelijk geverifieerde wereldbibliografie gepresenteerd. De bredere genres, onbekende extra werken, alle vervolgfilms, losse TV-afleveringen en korte films blijven een afzonderlijke auditopgave.','', '## Covers en posters — juiste noemers','', '| Groep | Werkrecords / bewezen zelfstandige verhalen | NL-cover beschikbaar | EN-cover beschikbaar | NL niet beschikbaar | EN niet beschikbaar |','| --- | ---: | ---: | ---: | ---: | ---: |',f"| Boeken en bundels | {len(B)} | {img['nl']} | {img['en']} | {len(missingNL)} | {len(missingEN)} |",f"| Aangetoonde zelfstandige verhaaluitgaven (deels dezelfde novellen als hierboven) | {len(standalone)} | {ownCounts['nl']} | {ownCounts['en']} | {len(standalone)-ownCounts['nl']} | {len(standalone)-ownCounts['en']} |",'',f"Er zijn {img['posters']} gecontroleerde Engelstalige posters bij {len(F)} adaptatierecords; {len(missingPosters)} posters ontbreken nog. De zelfstandige-verhalenrij is een **deels overlappende deelverzameling**, geen optelling bij de boekenrij. De vijf afzonderlijke Nederlandse uitgeversuitgaven zijn The Mist, A Good Marriage, Mile 81, In the Tall Grass en Throttle. Voor de getelde ontbrekende taalvarianten is niet automatisch vastgesteld dat een zelfstandige uitgave in die taal bestaat; editieonderzoek blijft nodig.", '', f"{A['storyCovers']['collectedStories']} individuele bijdragen hebben een geregistreerde standaardbundel en gebruiken de bundelcover ({coverUses['nl']} in NL, inclusief toegestane Engelse fallback; {coverUses['en']} in EN). Andere bundelrelaties blijven apart aanklikbaar. {A['storyCovers']['withoutRecordedCollection']} bijdragen hebben geen geregistreerde bundel. **Geen van deze bijdragen wordt als ontbrekende eigen cover geteld alleen omdat er geen zelfstandige boekuitgave is.** Een zelfstandige verhaalcover mag uitsluitend uit een aangetoonde editie komen; verhaalillustraties en filmposters worden niet tot covers gepromoveerd.", '', 'De beelddataset bevat alleen visueel op titel/taal beoordeelde beelden die bij ophalen echte afbeeldingsbestanden waren. Afgewezen: de NL-cover-URL voor Het verloren rijk gaf tekst “Not found”; een Lisey-uitgeverpagina gaf niet passend Engels promotiemateriaal; de aangeleverde Outsider-serieafbeelding was onvoldoende herkenbaar. Zij verschijnen niet als goedgekeurde cover/poster. Engelse fallback is zichtbaar gemarkeerd. Afbeeldingen blijven extern geladen met broncredit; er is geen vrije licentie of toestemming voor verdere herdistributie geclaimd. Bronnen kunnen later uitvallen; de layout behoudt dan een placeholder.','', '## Samenwerkingen en auteursrollen','', f"Alle {A['collaborations']['referenceEntries']} vermeldingen uit de officiële samenwerkingsindex zijn tegen de aanwezige werken vergeleken. Er zijn {A['collaborations']['uniqueRecordedProjects']} unieke geregistreerde samenwerkingsprojecten, inclusief Gwendy’s Button Box en Other Worlds Than These buiten die index. Drie links in de samenwerkingsindex verwijzen naar verouderde `/short_story/`-paden die 404 geven; de corresponderende werken bestaan wel op de actuele `/short/`-paden uit de hoofdlijst.", '', 'Het filter “Samenwerkingen / Collaborations” werkt op de boeken- en verhalenpagina. Peter Straub, Owen King, Richard Chizmar, Joe Hill en Stewart O’Nan zijn met auteursrollen vastgelegd. Richard Bachman is een schrijfnaam van Stephen King, geen extra co-auteur. American Vampire vermeldt de afzonderlijke verhaallijnen van King en Scott Snyder en illustrator Rafael Albuquerque. Nightmares in the Sky onderscheidt Kings tekst en fotografie van f-stop Fitzgerald. Mid-Life Confidential is een bijdragenbundel; de genoemde makerslijst is nog onvolledig en staat als zodanig gemarkeerd. Geen voorwoord of aanbeveling wordt als co-auteurschap geregistreerd. Andere gezamenlijke/afgeleide projecten, waaronder theater- en anthologiebijdragen buiten deze scope, vereisen aanvullend rollen- en editieonderzoek.','', '## Dark Tower en navigatie','', f"Er zijn {len(T)} onderbouwde connectierecords met concrete concepten, bron, tweetalige toelichting en zichtbaar zekerheidsniveau. Nieuwe/uitgewerkte koppelingen betreffen onder meer Dinky Earnshaw, UR, de Territories, Lud en Other Worlds Than These. De IT-schildpadkoppeling is interpretatief gelabeld; de bron bewijst geen identieke entiteit. Boeken en verhalen openen de gerelateerde werken rechtstreeks.", '', 'De vier cataloguspagina’s en individuele details hebben deelbare hash-URL’s, met herstel van zoeken/filteren/sorteren en browser terug/vooruit. De zichtbare zoekknop met vergrootglas, Enter en live zoeken delen dezelfde logica. Er is een afzonderlijke, tweetalige pagina Bronnen & Werkwijze.','', '## Toevoegingen en verplaatsingen','']
for change in A['changes']:
 if change.get('action') in ['added','moved-novel-to-book-contents']:lines.append(f"- {change['category']}: **{change['title']}** — {change['action']}.")
lines+=['', 'NL-titelcorrecties volgen de gecontroleerde editiebron, onder meer Vel over been (Bag of Bones), Rosie (Rose Madder), Het geheim van de Buick en Duma. Originele titels en eerdere naamvarianten blijven doorzoekbaar. De oorspronkelijke 1.4-weergavedata is bewaard in `data/legacy-v1.4.json`.','', '## Tegenstrijdigheden','', '| Werk | Verschil | Beslissing | Bron |','| --- | --- | --- | --- |']
for x in A['conflicts']:
 before=x.get('index',str(x.get('legacy',x.get('bibliography',''))));after=x.get('detail',x.get('current',''));lines.append(f"| {x['title']} | {before} / {after} | {x['decision']} | [Bron]({x['source']}) |")
lines+=['', 'Andere betekenisverschillen worden niet tot fouten platgeslagen: The Life of Chuck behoudt de festivalpremière in 2024, terwijl de bioscoopuitbreng in 2025 plaatsvond. Carrie is opnieuw tegen de actuele Amazon-bron gelegd: oktober 2026-release en verlenging zijn gedocumenteerd; de oudere miniserieclassificatie wijkt af van de huidige doorlopende serie. Geen datum voor seizoen 2 is verzonnen.','', '## Resterend onderzoek','', '### Nederlandse boek-/bundelcovers niet beschikbaar','']+[f'- {x}' for x in missingNL]+['', '### Engelse boek-/bundelcovers niet beschikbaar','']+([f'- {x}' for x in missingEN] or ['Geen ontbrekende Engelse boek-/bundelcover binnen de huidige bibliotheekselectie. Dit is geen claim over alle mogelijke edities.'])+['','### Posters niet beschikbaar','']+[f'- {x}' for x in missingPosters]+['','### Aanvullende film/TV-groepen buiten de afgeronde primaire vergelijking','']+[f'- {x}' for x in A['supplementaryScreenQueue']]+['','Deze groepen zijn geen definitieve telling van afzonderlijke ontbrekende records. Eerste publicaties, alle Nederlandse vertalingen en bundelinhouden, aanvullende co-auteursrollen en castinformatie vereisen verdere controle. De machineleesbare ledger somt per record de open velden op.','', '## Reproduceren en toetsen','', '```sh','python3 scripts/build_catalog.py','python3 scripts/report_quality.py','node --check app.js','node --check catalog.js','node --check media.js','node --check about.js','node --test tests/*.test.cjs','```','', 'Bronnen opnieuw ophalen gebeurt apart via `scripts/collect_reference.py` en `scripts/collect-dutch.py`, met cache en maximaal twee gelijktijdige verzoeken. Visuele goedkeuring wordt niet uit HTTP-succes afgeleid. `scripts/check_images.py` is voor een latere beeldcontrolefase en wijzigt zelf geen goedkeuringsstatus. `VALIDATION.md` beschrijft de daadwerkelijk uitgevoerde tests. Publicatiestatus wordt pas na deployment in de oplevering bevestigd.']
lines+=['', '## Update 1.5.1 — vier aanvullende film/TV-records', '', 'Carrie (2002), Carrie (2013), The Dead Zone (2002) en Haven (2010) zijn per veld gecontroleerd buiten de primaire King-lijst. De bronfeiten, rollen, datumsemantiek en beperkingen staan reproduceerbaar in `data/reference/screen-1.5.1.json`. De 96 film/TV-titels zijn nu alle tegen een benoemde bron vergeleken; dat is geen volledige verificatie van alle metadata.', '', 'IMDb levert aanvullende gebruikersscores en beschrijvingsfeiten. Scores zijn opgeslagen waarnemingen uit geïndexeerde IMDb-resultaten, geraadpleegd op 25 oktober 2026; de index kan ouder zijn. Het zijn geen live scores. Korte beschrijvingen zijn in eigen woorden geschreven. Bij de twee Carrie-records gebruiken de beschrijvingen productie-/distributeursfeiten, omdat de IMDb-hoofdpagina’s 403 gaven. De score van Carrie (2002) blijft expliciet onbevestigd. Geen toegangsbeperking is omzeild.', '', '| Record | Hoofdbron | Resultaat / grens |', '| --- | --- | --- |']
for e in load('data/reference/screen-1.5.1.json')['records']:
 lines.append(f"| {e['key']} | [Bron]({e['values']['Bron']}) | {'; '.join(e['notes']) or 'Titel, formaat, credits, bronwerk en releasedatum per veld vastgelegd.'} |")
lines+=['', 'Swank presenteert bij Carrie (2002) meerdere crewrollen samen onder Directors. Apple TV bevestigt afzonderlijk David Carson; de overige namen zijn niet als regisseurs overgenomen. De exacte TV-premièredatum blijft open omdat de volledige contemporaine Playbill-pagina 403 gaf. Demilo bevestigt voor Carrie (2013) de Amerikaanse bioscooprelease van 18 oktober 2013. Het contemporaine producenteninterview bij TV Tech bevestigt Michael Piller als showrunner van The Dead Zone en de USA-première van 16 juni 2002. Het Syfy-persbericht, gereproduceerd door AWN, bevestigt Haven op 9 juli 2010 in de VS versus 12 juli in Canada; Scott Shepherd is uitsluitend als showrunner van seizoen 1 vermeld. Haven is los geïnspireerd op The Colorado Kid.', '', 'Geen nieuwe afbeeldingen of verdere Nederlandse uitwerking in deze batch. Eerste-publicatieonderzoek volgt later.']
# Foundation is a separate shadow dataset; it must not alter catalog/cover denominators.
foundation=load('data/v2/manifest.json');rights=load('data/reviews/screen-data-rights.json')
lines+=['', '## Foundation 1.6 — beperkte schaduwmigratie', '', 'Naast de actieve catalogus staat nu een v2-proof of concept met uitsluitend The Talisman en Black House. De bestaande catalogus, runtime en beelddata blijven ongewijzigd. Er is geen volledige migratie en geen nieuwe Explorer-pagina. De nieuwe canonieke IDs zijn titelonafhankelijke nummers; oude IDs en detailhashes blijven als aliases bewaard.', '', 'De proef omvat twee werken, vier bestaande EN/NL-editievoorbeelden met editiegebonden covers, twee personen, vier co-auteurscredits, twee personages, één locatie, acht relaties, vijf bronnen en veldgerichte verificatieclaims. Twee externe Tower-verwijzingen worden tegen de legacycatalogus opgelost en zijn geen extra gemigreerde werken. Bundel-/adaptatietabellen blijven leeg: geen bundelinhoud of projectstatus is verzonnen.', '', 'De officiële werkpagina’s en Tower Connections zijn voor de geselecteerde feiten geraadpleegd. Nederlandse editievoorbeelden gebruiken de bestaande uitgeverssnapshots; zij zijn niet als nieuwe editieaudit gepresenteerd. Druk, vertaler en eerste-publicatiegeschiedenis blijven open. Interpretatieve zekerheid wordt door schema en tests ondersteund; er is geen nieuwe theorie toegevoegd om een label te vullen.', '', '### Huidige scores en omschrijvingen: hergebruik ter beoordeling', '', 'Er is geen OMDb- of IMDb-API-integratie. Vier IMDb-objecten komen uit handmatig opgeslagen waarnemingen van geïndexeerde zoekresultaten in 1.5.1. Drie scores en de twee op IMDb-feiten gebaseerde eigen omschrijvingen hebben geen aangetroffen toestemmingsbewijs en zijn als needs-review geregistreerd in `data/reviews/screen-data-rights.json`. De Carrie-omschrijvingen zijn eigen redactionele teksten op andere, afzonderlijk genoemde bronfeiten. Bestaande data blijft binnen deze foundation intact; geen recht op herpublicatie wordt daarmee aangenomen en deze velden zijn niet als toegestane v2-import overgenomen.', '', '[IMDb beschrijft beperkingen op extractie en herpublicatie](https://help.imdb.com/article/imdb/general-information/can-i-use-imdb-data-in-my-software/G5JTRESSHJBBHTGX). Betaalde IMDb-API’s en abonnementen zijn uitgesloten. Een mogelijke kosteloze route is [TMDb onder de toepasselijke voorwaarden](https://developer.themoviedb.org/docs/faq): eerst geschiktheid en volledige voorwaarden vaststellen, vereiste attributie toepassen, en een TMDb-score nooit IMDb noemen. Er is geen account/key/dienst geactiveerd. De directe veilige fallback is een externe verwijzing zonder onbevestigd overgenomen score plus eigen korte tekst uit gecontroleerde productiefeiten.', '', 'Validator: `npm ci --ignore-scripts`, daarna `npm run validate:foundation`. Volledige tests: `npm test`. De validator controleert JSON Schema, register/referenties, bronclaims, rollen, datums, ISBN, relaties, bundelinhoud, coverkoppelingen en oude routes; runtimehashes bewaken dat de bestaande site intact blijft. Werkelijke test-/browserresultaten en beperkingen staan in `FOUNDATION-DELIVERY.md`. De bibliografische/beeldtellingen hierboven blijven die van de actieve catalogus.']
